// Extract message details from WhatsApp Cloud API webhook payload.
const body = $input.first().json.body;
const entry   = (body?.entry        || [])[0];
const changes = (entry?.changes      || [])[0];
const value   = changes?.value       || {};
const messages = value?.messages     || [];

if (messages.length === 0) {
  // Webhook verification or status update — skip
  return [];
}

const msg = messages[0];
const from = msg.from; // sender's phone (E.164 without '+')

// Only handle image messages for expense submissions
if (msg.type !== 'image') {
  return [{ json: { skip: true, reason: 'not_image', from } }];
}

const image = msg.image || {};
return [{
  json: {
    skip:         false,
    from,
    media_id:     image.id,
    mime_type:    image.mime_type,
    caption:      image.caption || '',
    wa_msg_id:    msg.id,
    timestamp:    msg.timestamp
      ? new Date(parseInt(msg.timestamp) * 1000).toISOString()
      : new Date().toISOString(),
  }
}];

// Build a unique S3/R2 object key for this receipt.
const from = $('Parse WhatsApp Payload').first().json.from;
const ts   = $('Parse WhatsApp Payload').first().json.timestamp;
const mime = $('Parse WhatsApp Payload').first().json.mime_type || 'image/jpeg';
const ext  = mime.split('/')[1] || 'jpg';

const date = new Date(ts);
const ymd  = `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;

const key = `expenses/${from}/${ymd}/${Date.now()}.${ext}`;

return [{
  json: {
    ...($('Parse WhatsApp Payload').first().json),
    r2_key: key,
    mime_type: mime,
  }
}];

const upload  = $('Upload to Cloudflare R2').first().json;
const wa      = $('Parse WhatsApp Payload').first().json;
const emp     = $input.first().json;
const caption = wa.caption || '';

// Try to parse an amount from the caption, e.g. '₹450 taxi'
const amountMatch = caption.match(/(₹|Rs\.?|INR)?\s*(\d+(\.\d{1,2})?)/);
const amount = amountMatch ? parseFloat(amountMatch[2]) : null;

const r2Url = `https://${$env.R2_BUCKET_NAME}.${$env.R2_ACCOUNT_ID}.r2.cloudflarestorage.com/${wa.r2_key}`;

return [{
  json: {
    employee_id:   emp?.id          || null,
    employee_name: emp?.name        || 'Unknown',
    phone:         wa.from,
    caption:       caption,
    amount:        amount,
    currency:      'INR',
    receipt_url:   r2Url,
    r2_key:        wa.r2_key,
    wa_msg_id:     wa.wa_msg_id,
    submitted_at:  wa.timestamp,
    status:        'pending_review',
  }
}];

